/** 徽章中文名 -> badge_key（后台改过名的库也能命中素材） */
export const BADGE_ART_BY_NAME = {
  '一年老用户': 'user_1y',
  '二年老用户': 'user_2y',
  '三年老用户': 'user_3y',
  '四年老用户': 'user_4y',
  '五年老用户': 'user_5y',
  '连续打卡7天': 'signin_7',
  '连续打卡30天': 'signin_30',
  '连续打卡100天': 'signin_100',
  '初言者': 'first_comment',
  '评论达人': 'comment_master',
  '回复能手': 'reply_expert',
  '热心答主': 'answer_helper',
  '热评常客': 'hot_comment',
  '沙发达人': 'sofa_hunter',
  '收藏爱好者': 'favorite_lover',
  '暖心点赞手': 'like_giver',
  '社交达人': 'social_butterfly',
  '多产写手 Lv1': 'writer_lv1',
  '多产写手 Lv2': 'writer_lv2',
  '多产写手 Lv3': 'writer_lv3',
  '图文达人': 'image_master',
  '视频创作者': 'video_creator',
  '精华贡献者': 'featured_contributor',
  '爆款作者': 'viral_author',
  '优质创作者': 'quality_creator',
  '话题贡献者': 'topic_contributor',
  '活动参与者': 'activity_participant',
  '圈主': 'circle_owner',
  '圈子管理员': 'circle_admin',
}

/**
 * 取徽章素材的 data-URI；没有专属素材返回空串（调用方回退到 Icon）
 * @param {object|null} badge 徽章对象，需含 badge_key（可选 name）
 * @returns {string}
 */
export function badgeArtSrc(badge) {
  if (!badge) return ''
  const key = badge.badge_key || BADGE_ART_BY_NAME[badge.name] || ''
  const art = BADGE_ART[key]
  if (!art) return ''
  const svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="' + art.vb + '">' + art.body + '</svg>'
  return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg)
}
